# Corrected analysis

test_input = [
    [7, 7, 7, 2, 2, 2, 7, 7, 7, 7, 7],  # row 0: 2s at cols 3,4,5
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 3, 7, 7, 7, 7, 7, 7],  # row 3: 3 at col 4
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 3, 7, 3, 7, 7, 7, 7, 7],  # row 7: 3s at cols 3,5
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7],
]

# Background = 7
# Count non-7 values per column
col_counts = {c: 0 for c in range(11)}
for r in range(14):
    for c in range(11):
        if test_input[r][c] != 7:
            col_counts[c] += 1

print("Column counts:", col_counts)

# Max column count
max_count = max(col_counts.values())
print(f"Max count: {max_count}")
for c, count in col_counts.items():
    if count == max_count:
        print(f"  Column {c} has {count} values")

# Also count per row for reference
row_counts = {r: 0 for r in range(14)}
for r in range(14):
    for c in range(11):
        if test_input[r][c] != 7:
            row_counts[r] += 1
print("Row counts:", {r: count for r, count in row_counts.items() if count > 0})

# Position of each value
positions_by_value = {v: [] for v in [2, 3]}
for r in range(14):
    for c in range(11):
        if test_input[r][c] != 7:
            val = test_input[r][c]
            positions_by_value[val].append((r, c, count))  # We'll add count from col

print("Positions by value:")
for v, pos in positions_by_value.items():
    for r, c, _ in pos:
        print(f"  Value {v} at ({r}, {c}), col_count={col_counts[c]}")

